// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;

class MemoryFloatingPointComparisonRegressionTest {

	@Test
	void bindAndMembershipExpressionsUseNumericValueEquality() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(connection.prepareTupleQuery(
					"PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> "
							+ "SELECT ?value ?equal ?different ?greater ?member ?nonmember WHERE { "
							+ "VALUES ?value { \"NaN\"^^xsd:float \"NaN\"^^xsd:double \"-0\"^^xsd:float \"0\"^^xsd:double } "
							+ "BIND(?value = ?value AS ?equal) BIND(?value != ?value AS ?different) "
							+ "BIND(?value > 1 AS ?greater) "
							+ "BIND(?value IN (?value) AS ?member) BIND(?value NOT IN (?value) AS ?nonmember) }")
					.evaluate());
			assertEquals(4, rows.size());
			for (BindingSet row : rows) {
				boolean nan = row.getValue("value").stringValue().equals("NaN");
				assertEquals(connection.getValueFactory().createLiteral(!nan), row.getValue("equal"), row.toString());
				assertEquals(connection.getValueFactory().createLiteral(nan), row.getValue("different"),
						row.toString());
				assertEquals(connection.getValueFactory().createLiteral(false), row.getValue("greater"),
						row.toString());
				assertEquals(connection.getValueFactory().createLiteral(!nan), row.getValue("member"), row.toString());
				assertEquals(connection.getValueFactory().createLiteral(nan), row.getValue("nonmember"),
						row.toString());
			}
		} finally {
			repository.shutDown();
		}
	}
}
